cat > $TMPDIR/T.java << 'EOF'
import java.io.StringReader;
public class T {
    public static void main(String[] args) throws Exception {
        Class<?> c = Class.forName("org.apache.commons.csv.ExtendedBufferedReader");
        java.lang.reflect.Constructor<?> ctor = c.getDeclaredConstructor(java.io.Reader.class);
        ctor.setAccessible(true);
        Object br = ctor.newInstance(new StringReader("12\r\n34"));
        java.lang.reflect.Method read = c.getDeclaredMethod("read", char[].class, int.class, int.class);
        read.setAccessible(true);
        char[] buf = new char[6];
        Object len = read.invoke(br, buf, 0, 6);
        System.out.println("len=" + len);
        System.out.println("buf=" + new String(buf));
        java.lang.reflect.Method getLineNumber = c.getDeclaredMethod("getLineNumber");
        getLineNumber.setAccessible(true);
        System.out.println("lineNumber=" + getLineNumber.invoke(br));
    }
}
EOF
javac -cp target/classes -d $TMPDIR $TMPDIR/T.java
java -cp target/classes:$TMPDIR T
